// The gallery example's transpile output: developer-owned generated source and
// the tests that drive it. This example exercises cross-base unions (Reference §9
// extended; OQ29) — a static union as a field's target type, the inverse it
// infers onto every operand, a derived body on the union, a rule over a
// refinement of the union, and per-operand narrowing. Regenerated by
// `gradle generate`.
plugins {
    kotlin("jvm")
}

group = "velle"

repositories {
    mavenCentral()
}

dependencies {
    implementation(project(":compiler"))
    testImplementation(kotlin("test"))
    testImplementation(project(":stores:sqlite")) // the flows re-run over real storage
}

tasks.test {
    useJUnitPlatform()
}

tasks.register<JavaExec>("generate") {
    description = "Regenerate the Gallery typed surface and executable specs from gallery.velle"
    classpath = sourceSets["main"].runtimeClasspath
    mainClass.set("velle.GenerateKt")
    args("../gallery.velle", "Gallery")
}

kotlin {
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_21)
    }
}

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}
